package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.*;
import static org.junit.jupiter.api.Assertions.*;

class JdbcPointExchangesTest extends JdbcPointLedgerTest {
 PointExchanges exchanges;PointExchangeCatalog catalog;
 @BeforeEach void exchanges(){jdbc.execute("DROP TRIGGER IF EXISTS fail_point_exchange");jdbc.execute("DROP TRIGGER IF EXISTS fail_point_stock");jdbc.update("DELETE FROM point_exchange_record");jdbc.update("DELETE FROM point_exchange_catalog");jdbc.update("UPDATE auth_session SET point_identity_source='VERIFIED_WECHAT' WHERE role='OWNER'");catalog=new PointExchangeCatalog(db,coupons,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())));exchanges=new PointExchanges(db,catalog,coupons,ledger,true);}
 long offer(int quantity,int cost,int limit){long c=publish(quantity);coupons.pool(operator,c,key(),json.createObjectNode().put("selected",true).put("expected_pool_revision",0));return directory(c,cost,limit);}
 long directory(long c,int cost,int limit){var b=json.createObjectNode().put("coupon_id",c).put("publication_revision",2).put("pool_revision",1).put("points_cost",cost).put("per_owner_limit",limit).put("source_note","合成测试目录来源").put("valid_from",clock.value.toString()).put("valid_to",clock.value.plusSeconds(1800).toString());long id=catalog.create(operator,key(),b).path("data").path("id").asLong();catalog.status(operator,id,key(),statusBody(1,"PUBLISHED"));return id;}
 ObjectNode request(long p){return json.createObjectNode().put("catalog_id",p).put("catalog_revision",2);}
 void earn(com.autocare.platform.vehicle.VehicleOwner a){var ps=jdbc.queryForList("SELECT id FROM point_task_policy WHERE task_type='CHECK_IN' AND status='PUBLISHED'");long id=ps.isEmpty()?policy("CHECK_IN"):ReservationStore.number(ps.get(0),"id");var event=ledger.checkin(a,key(),check(id));assertTrue(ledger.credit(event.path("data").path("event_id").asLong()));}
 long balance(){return ((Number)ledger.overview(owner).get("balance")).longValue();}
 @Test void oneSuccessAtomicallyBindsEvidenceDebitCouponStockAndAudit(){earn(owner);long p=offer(2,5,2);String k=key();var b=request(p);var result=exchanges.exchange(owner,k,b);assertEquals(result,exchanges.exchange(owner,k,b));assertEquals(2,balance());assertEquals(1,count("point_exchange_record"));assertEquals(1,count("coupon_issue"));assertEquals(2,count("point_verified_entry"));assertEquals("POINTS",jdbc.queryForObject("SELECT origin FROM coupon_issue",String.class));assertEquals(result.path("data").path("exchange_id").asLong(),jdbc.queryForObject("SELECT points_exchange_id FROM coupon_issue",Long.class));assertEquals(-5,jdbc.queryForObject("SELECT delta FROM point_verified_entry WHERE exchange_id IS NOT NULL",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE action='POINT_EXCHANGE'",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT issued_quantity FROM coupon",Integer.class));assertEquals(1L,exchanges.list(owner,1).get("total"));assertEquals(0L,exchanges.list(peer,1).get("total"));assertFalse(db.json(exchanges.list(owner,1)).contains("submission_hash"));assertFalse(db.json(exchanges.list(owner,1)).contains("identity_session"));var flows=(List<?>)ledger.flow(owner,1).get("items");assertEquals(2,flows.size());var debit=(Map<?,?>)flows.get(0);assertTrue(debit.containsKey("exchange_id"));assertFalse(debit.containsKey("task_type"));assertEquals(-5,((Number)debit.get("delta")).intValue());}
 @Test void legacyBalancesAndPendingEventsCannotPayAndExactBalanceCanReachZero(){long p=offer(2,7,2);jdbc.update("UPDATE user SET point_balance=99999 WHERE id=1");assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p))));long event=checkin(policy("CHECK_IN"));assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p))));assertTrue(ledger.credit(event));exchanges.exchange(owner,key(),request(p));assertEquals(0,balance());assertEquals(99999,jdbc.queryForObject("SELECT point_balance FROM user WHERE id=1",Integer.class));assertEquals(0,count("point_flow"));assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p))));assertEquals(1,count("point_exchange_record"));}
 @Test void unknownTestWrongAppAndDisabledNewWritesAreRejectedButEarningSwitchIsIndependent(){earn(owner);long p=offer(3,2,3);for(String source:List.of("TEST","UNKNOWN")){jdbc.update("UPDATE auth_session SET point_identity_source=? WHERE id=?",source,owner.session());assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p))));}jdbc.update("UPDATE auth_session SET point_identity_source='VERIFIED_WECHAT' WHERE id=?",owner.session());assertEquals(409,code(()->new PointExchanges(db,catalog,coupons,ledger,false).exchange(owner,key(),request(p))));assertEquals(409,code(()->new PointExchanges(db,catalog,coupons,new PointLedger(db,policies,"other-app",true,true),true).exchange(owner,key(),request(p))));new PointExchanges(db,catalog,coupons,new PointLedger(db,policies,"test-app",false,false),true).exchange(owner,key(),request(p));assertEquals(5,balance());}
 @Test void templateQuotaAccumulatesAcrossStoppedCatalogAndPriceVersions(){earn(owner);long first=offer(8,2,1);long c=ReservationStore.number(catalog.row(first,false),"coupon_id");exchanges.exchange(owner,key(),request(first));catalog.status(operator,first,key(),statusBody(2,"STOPPED"));long second=directory(c,1,1);assertEquals(409,code(()->exchanges.exchange(owner,key(),request(second))));catalog.status(operator,second,key(),statusBody(2,"STOPPED"));long third=directory(c,1,2);exchanges.exchange(owner,key(),request(third));assertEquals(4,balance());assertEquals(2,count("point_exchange_record"));assertEquals(409,code(()->exchanges.exchange(owner,key(),request(third))));}
 @Test void publicOnceAndExchangeLimitsAreIndependent(){earn(owner);long p=offer(4,2,2),c=ReservationStore.number(catalog.row(p,false),"coupon_id");coupons.claim(owner,key(),claimBody(c));exchanges.exchange(owner,key(),request(p));exchanges.exchange(owner,key(),request(p));assertEquals(409,code(()->coupons.claim(owner,key(),claimBody(c))));assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p))));assertEquals(3,count("coupon_issue"));assertEquals(3,balance());}
 @Test void insufficientStockDoesNotDebitAndNewInstanceReplaysAfterSourceStoppedExpiredAndSwitchOff(){earn(owner);long p=offer(1,2,3);String k=key();var b=request(p);var first=exchanges.exchange(owner,k,b);assertEquals(409,code(()->exchanges.exchange(owner,key(),b)));catalog.status(operator,p,key(),statusBody(2,"STOPPED"));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");jdbc.update("UPDATE merchant SET status=0 WHERE id=1");clock.value=clock.value.plusSeconds(4000);var replay=new PointExchanges(db,catalog,coupons,ledger,false).exchange(owner,k,b);assertEquals(first.path("data"),replay.path("data"));assertEquals(5,balance());assertEquals(1,count("point_exchange_record"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM audit_log WHERE action='POINT_EXCHANGE'",Integer.class));}
 @Test void originalKeyRejectsChangedBodyBeforeAndAfterGenericExpiryAndReauthorizes(){earn(owner);long a=offer(4,1,4),b=offer(4,1,4);String k=key();exchanges.exchange(owner,k,request(a));assertEquals(400,code(()->exchanges.exchange(owner,k,request(b))));jdbc.update("UPDATE idempotency_record SET expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 2 DAY)");assertEquals(400,code(()->exchanges.exchange(owner,k,request(b))));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());assertEquals(401,code(()->exchanges.exchange(owner,k,request(a))));assertEquals(401,code(()->exchanges.list(owner,1)));}
 @Test void sourcePoolRevisionAndStopInvalidateNewExchangeWithoutSpending(){earn(owner);long p=offer(4,2,3),c=ReservationStore.number(catalog.row(p,false),"coupon_id");assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p).put("catalog_revision",1))));coupons.pool(operator,c,key(),json.createObjectNode().put("selected",false).put("expected_pool_revision",1));assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p))));coupons.pool(operator,c,key(),json.createObjectNode().put("selected",true).put("expected_pool_revision",2));assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p))));assertEquals(7,balance());assertEquals(0,count("point_exchange_record"));}
 @Test void merchantProjectAndDeadlineFailuresLeaveNoPartialExchange(){earn(owner);long p=offer(4,2,3);jdbc.update("UPDATE merchant_project SET on_shelf=0 WHERE id=1");assertEquals(404,code(()->exchanges.exchange(owner,key(),request(p))));jdbc.update("UPDATE merchant_project SET on_shelf=1 WHERE id=1");clock.value=clock.value.plusSeconds(1800);assertEquals(409,code(()->exchanges.exchange(owner,key(),request(p))));assertEquals(7,balance());assertEquals(0,count("coupon_issue"));}
 @Test void auditFailureRollsBackEveryBusinessWriteAndOriginalRequestRetries(){earn(owner);long p=offer(3,2,3);String k=key();jdbc.execute("CREATE TRIGGER fail_point_exchange BEFORE INSERT ON audit_log FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->exchanges.exchange(owner,k,request(p))));assertEquals(7,balance());assertEquals(0,count("point_exchange_record"));assertEquals(0,count("user_coupon"));assertEquals(0,count("coupon_issue"));assertEquals(0,count("coupon_stock_event"));assertEquals(1,count("point_verified_entry"));assertEquals(0,jdbc.queryForObject("SELECT issued_quantity FROM coupon",Integer.class));jdbc.execute("DROP TRIGGER fail_point_exchange");exchanges.exchange(owner,k,request(p));assertEquals(5,balance());}
 @Test void failureAfterDebitAlsoRollsBackCouponAndPermanentReceipt(){earn(owner);long p=offer(3,2,3);String k=key();jdbc.execute("CREATE TRIGGER fail_point_stock BEFORE INSERT ON coupon_stock_event FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");assertEquals(503,code(()->exchanges.exchange(owner,k,request(p))));assertEquals(7,balance());assertEquals(0,count("point_exchange_record"));assertEquals(0,count("user_coupon"));assertEquals(0,count("coupon_issue"));assertEquals(1,count("point_verified_entry"));jdbc.execute("DROP TRIGGER fail_point_stock");exchanges.exchange(owner,k,request(p));assertEquals(5,balance());}
 @Test void concurrentDifferentKeysCannotOverspendOneAccount()throws Exception{earn(owner);long a=offer(3,5,3),b=offer(3,5,3);race(List.of(()->exchanges.exchange(owner,key(),request(a)),()->exchanges.exchange(owner,key(),request(b))));assertEquals(2,balance());assertEquals(1,count("point_exchange_record"));}
 @Test void concurrentDifferentOwnersCannotIssueLastCouponTwice()throws Exception{earn(owner);earn(peer);long p=offer(1,5,3);var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var results=new ArrayList<Future<Integer>>();for(var a:List.of(owner,peer))results.add(pool.submit(()->{start.await();try{exchanges.exchange(a,key(),request(p));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}}));start.countDown();var codes=new ArrayList<Integer>();for(var result:results)codes.add(result.get(30,TimeUnit.SECONDS));Collections.sort(codes);assertEquals(List.of(200,409),codes,()->new org.springframework.jdbc.core.JdbcTemplate(new DriverManagerDataSource(mysql.getJdbcUrl(),"root",mysql.getPassword())).queryForList("SHOW ENGINE INNODB STATUS").toString());}finally{pool.shutdownNow();}assertEquals(1,count("point_exchange_record"));assertEquals(1,count("coupon_issue"));assertEquals(9,jdbc.queryForObject("SELECT SUM(balance) FROM point_verified_account",Integer.class));}
 @Test void concurrentSameKeyReturnsOneSuccessAndOnePermanentFact()throws Exception{earn(owner);long p=offer(3,2,3);String k=key();var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->exchanges.exchange(owner,k,request(p)));var b=pool.submit(()->exchanges.exchange(owner,k,request(p)));assertEquals(a.get(30,TimeUnit.SECONDS),b.get(30,TimeUnit.SECONDS));assertEquals(5,balance());assertEquals(1,count("point_exchange_record"));}finally{pool.shutdownNow();}}
 @Test void sourceLockWaitRechecksDirectoryDeadlineBeforeSpending()throws Exception{earn(owner);long p=offer(3,2,3);var pool=Executors.newSingleThreadExecutor();try(var c=jdbc.getDataSource().getConnection()){c.setAutoCommit(false);try(var q=c.createStatement()){q.executeQuery("SELECT id FROM merchant WHERE id=1 FOR UPDATE");}var result=pool.submit(()->{try{exchanges.exchange(owner,key(),request(p));return 200;}catch(org.springframework.web.server.ResponseStatusException e){return e.getStatusCode().value();}});var diagnostics=new org.springframework.jdbc.core.JdbcTemplate(new DriverManagerDataSource(mysql.getJdbcUrl(),"root",mysql.getPassword()));boolean waiting=false;long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(System.nanoTime()<end){if(diagnostics.queryForList("SELECT trx_state,trx_query FROM information_schema.innodb_trx").stream().anyMatch(r->"LOCK WAIT".equals(r.get("trx_state"))&&String.valueOf(r.get("trx_query")).contains("merchant"))){waiting=true;break;}Thread.sleep(100);}assertTrue(waiting,"observe actual source wait");clock.value=clock.value.plusSeconds(1800);c.commit();assertEquals(409,result.get(30,TimeUnit.SECONDS));assertEquals(7,balance());assertEquals(0,count("point_exchange_record"));}finally{pool.shutdownNow();}}
 @Test void signedLedgerAndIssuanceConstraintsRejectMissingOrMixedEvidence(){assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("INSERT INTO point_verified_entry(user_id,event_id,delta,balance_after,created_at) VALUES(1,123,-1,0,UTC_TIMESTAMP())"));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("INSERT INTO point_verified_entry(user_id,exchange_id,delta,balance_after,created_at) VALUES(1,123,1,1,UTC_TIMESTAMP())"));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("INSERT INTO point_verified_entry(user_id,event_id,exchange_id,delta,balance_after,created_at) VALUES(1,123,123,1,1,UTC_TIMESTAMP())"));earn(owner);long p=offer(2,2,2);exchanges.exchange(owner,key(),request(p));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE coupon_issue SET origin='INVITE'"));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE coupon_issue SET points_exchange_id=NULL"));}
 @Test void strictPayloadCannotOverrideIdentityOrPrice(){for(String raw:List.of("{}",request(1).put("points_cost",1).toString(),request(1).put("user_id",2).toString(),request(0).toString(),request(1).put("catalog_revision",1.5).toString(),request(1)+"{}"))assertThrows(Exception.class,()->PointExchanges.input(raw));assertThrows(Exception.class,()->exchanges.list(owner,0));}
 @Test void differentOwnersCanConcurrentlyCaptureAndCreditCheckins()throws Exception{policy("CHECK_IN");var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{start.await();earn(owner);return true;});var b=pool.submit(()->{start.await();earn(peer);return true;});start.countDown();assertTrue(a.get(30,TimeUnit.SECONDS));assertTrue(b.get(30,TimeUnit.SECONDS));assertEquals(2,count("point_task_event"));assertEquals(2,count("point_verified_entry"));assertEquals(14,jdbc.queryForObject("SELECT SUM(balance) FROM point_verified_account",Integer.class));}finally{pool.shutdownNow();}}
 @Test void guessedFutureDraftRevisionCannotSpendBeforePublication(){earn(owner);long p=offer(3,2,3);var source=catalog.view(catalog.row(p,false));var body=json.createObjectNode();for(String k:List.of("coupon_id","publication_revision","pool_revision","points_cost","per_owner_limit","source_note","valid_from","valid_to"))body.set(k,json.valueToTree(source.get(k)));long draft=catalog.create(operator,key(),body).path("data").path("id").asLong();assertEquals(409,code(()->exchanges.exchange(owner,key(),request(draft))));assertEquals(7,balance());assertEquals(0,count("point_exchange_record"));}
 @Test void differentOperatorsCanCreateDraftsAgainstSameSourceWithoutReceiptGapDeadlock()throws Exception{long p=offer(4,2,3);var first=catalog.row(p,false);jdbc.update("INSERT INTO operator_account(id,account,password_hash,phone,can_points) VALUES(2,'point-creator','unused','13800000001',1)");var peerOp=new OperatorActor(2,session(2,"operator_account","OPERATOR",OperatorActor.APP,null),java.time.Instant.now().plusSeconds(600));var b=json.createObjectNode().put("coupon_id",ReservationStore.number(first,"coupon_id")).put("publication_revision",2).put("pool_revision",1).put("points_cost",3).put("per_owner_limit",3).put("source_note","合成并发来源").put("valid_from",clock.value.toString()).put("valid_to",clock.value.plusSeconds(1800).toString());var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{start.await();return catalog.create(operator,key(),b);});var c=pool.submit(()->{start.await();return catalog.create(peerOp,key(),b);});start.countDown();assertNotEquals(a.get(30,TimeUnit.SECONDS).path("data").path("id"),c.get(30,TimeUnit.SECONDS).path("data").path("id"));assertEquals(3,count("point_exchange_catalog"));}finally{pool.shutdownNow();}}
}
